/** @type {Handler} */
export const handler = async (input) => {
  const ri = input.resistencia_insulina_confirmada === true;
  const riSevera = String(input.grado_resistencia || '').toLowerCase() === 'severa';
  const pmos = input.diagnostico_pmos_confirmado === true;
  const perdidaPeso = String(input.objetivo_principal || '').toLowerCase() === 'perdida_peso';
  const imcObesidad = typeof input.imc === 'number' && input.imc >= 30;
  const esAlto = (valor) => ['alto', 'alta', 'frecuente', 'muy_alto', 'muy_alta'].includes(String(valor || '').toLowerCase());
  const azucarAlta = esAlto(input.consumo_azucar) || esAlto(input.consumo_bebidas_azucaradas);
  const ultraprocesadosAltos = esAlto(input.consumo_ultraprocesados);

  let enfoque = 'alimentacion_equilibrada';
  let prioridad = 'mantenimiento_salud';
  let proteinas = 25;
  let carbohidratos = 45;
  let grasas = 30;
  let fibra = typeof input.fibra_diaria === 'number' ? input.fibra_diaria : 25;
  let calorias = typeof input.calorias_objetivo === 'number' ? input.calorias_objetivo : 0;
  const recomendaciones = [];
  const restricciones = [];
  const alertas = [];

  if (ri) {
    enfoque = 'bajo_indice_glucemico_alto_fibra';
    proteinas = 30; carbohidratos = 35; grasas = 35; fibra = Math.max(fibra, 30);
    recomendaciones.push('Reducir azucares simples y harinas refinadas.');
  }
  if (riSevera) {
    prioridad = 'control_glucemico';
    proteinas = 30; carbohidratos = 30; grasas = 40; fibra = Math.max(fibra, 30);
    alertas.push('Requiere control estricto de carbohidratos.');
  }
  if (pmos) {
    enfoque = 'antiinflamatorio_bajo_indice_glucemico';
    recomendaciones.push('Priorizar alimentos antiinflamatorios, fibra y una ingesta adecuada de proteina.');
  }
  if (perdidaPeso) {
    prioridad = 'deficit_calorico_moderado';
    calorias = calorias > 0 ? Math.max(calorias, 1200) : 1200;
    recomendaciones.push('Aplicar un deficit calorico moderado con seguimiento profesional.');
  }
  if (imcObesidad) prioridad = 'reduccion_peso_y_riesgo_metabolico';
  if (azucarAlta) restricciones.push('Azucares simples y bebidas azucaradas.');
  if (ultraprocesadosAltos) recomendaciones.push('Reducir el consumo de alimentos ultraprocesados.');
  if (input.ansiedad_por_comida === true) recomendaciones.push('Fraccionar las comidas y priorizar alimentos de alta saciedad.');
  if (input.cena_tardia === true) recomendaciones.push('Adelantar el horario de la cena.');

  const listas = ['alergias', 'intolerancias', 'alimentos_restringidos', 'alimentos_no_tolerados', 'alimentos_rechazados'];
  for (const campo of listas) {
    if (Array.isArray(input[campo])) {
      for (const alimento of input[campo]) {
        if (alimento !== null && alimento !== '' && !restricciones.includes(String(alimento))) restricciones.push(String(alimento));
      }
    }
  }

  const condicion = riSevera ? 'resistencia a la insulina severa' : ri ? 'resistencia a la insulina' : pmos ? 'PMOS' : 'los datos nutricionales disponibles';
  return {
    enfoque_nutricional_experto: enfoque,
    prioridad_nutricional: prioridad,
    calorias_sugeridas: calorias,
    proteinas_porcentaje: proteinas,
    carbohidratos_porcentaje: carbohidratos,
    grasas_porcentaje: grasas,
    fibra_sugerida: fibra,
    recomendaciones,
    restricciones,
    alertas,
    conclusion: `Recomendacion nutricional base orientada por ${condicion}.`
  };
};
